{
  "name": "donice-evaluator",
  "version": "0.1.0",
  "description": "OpenCode plugin: lock an agent into a milestone-based target with deterministic + LLM evaluators and a steering loop.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "evaluator",
    "milestones",
    "llm"
  ],
  "homepage": "https://github.com/Rorical/DoNice#readme",
  "bugs": {
    "url": "https://github.com/Rorical/DoNice/issues"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Rorical/DoNice.git"
  },
  "license": "MIT",
  "author": "Rorical",
  "type": "module",
  "main": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "commands",
    "README.md",
    "LICENSE"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "*"
  },
  "engines": {
    "bun": ">=1.0.0"
  }
}

import { type Plugin, tool } from "@opencode-ai/plugin"
import { mkdir, readFile, readdir, rm, stat, writeFile } from "node:fs/promises"
import { existsSync } from "node:fs"
import { dirname, join, resolve, relative, isAbsolute } from "node:path"
import { fileURLToPath } from "node:url"

// Directory of THIS file at runtime — used to locate the bundled
// commands/ folder. Works whether the plugin is loaded from the npm
// cache (~/.cache/opencode/node_modules/...) or from a local source
// checkout.
const PLUGIN_PKG_DIR = dirname(fileURLToPath(import.meta.url))

type Milestone = {
  id: string
  title: string
  description: string
  // Filenames in private/tests/. Empty/undefined = run nothing for this phase.
  tests?: string[]
  // Path relative to private/, e.g. "milestones/m1.md". Empty/undefined =
  // skip LLM review for this milestone.
  rubric?: string
}

type TargetSpec = {
  title: string
  description: string
  evaluatorModel?: { providerID: string; modelID: string }
  enableDeterministic?: boolean
  enableLLM?: boolean
  maxSteerIterations?: number
  steerCooldownMs?: number
  milestones?: Milestone[]
}

type Issue = { what: string; how_to_fix: string }
type LLMResult = { passed: boolean; summary: string; issues: Issue[] } | null
type EvalReport = {
  milestoneIdx: number
  milestone: Milestone
  passed: boolean
  detResults: { name: string; passed: boolean; summary: string }[]
  llmResult: LLMResult
  ranDeterministic: boolean
  ranLLM: boolean
}

const PUBLIC_TARGET_FILE = "target.json"
const PRIVATE_DIR_NAME = "private"
const TESTS_DIR_NAME = "tests"
const MILESTONES_DIR_NAME = "milestones"
const LEGACY_RUBRIC_FILE = "rubric.md"

type LogFn = (
  level: "debug" | "info" | "warn" | "error",
  message: string,
  extra?: Record<string, unknown>,
) => Promise<void>

async function bootstrapCommands(opts: {
  bundledDir: string
  targetDir: string
  log: LogFn
}) {
  const { bundledDir, targetDir, log } = opts
  if (!existsSync(bundledDir)) return // running outside a published layout
  let entries: string[]
  try {
    entries = await readdir(bundledDir)
  } catch {
    return
  }
  const stubs = entries.filter(
    (n) => n.endsWith(".md") && n.startsWith("donice-"),
  )
  if (!stubs.length) return
  await mkdir(targetDir, { recursive: true })
  let written = 0
  for (const name of stubs) {
    const dest = join(targetDir, name)
    if (existsSync(dest)) continue
    try {
      const content = await readFile(join(bundledDir, name), "utf8")
      await writeFile(dest, content, "utf8")
      written++
    } catch (err) {
      await log("warn", `failed to seed command ${name}`, { err: String(err) })
    }
  }
  if (written) {
    await log(
      "info",
      `bootstrapped ${written} donice-* slash command file(s) into ${targetDir} — restart OpenCode for the TUI to pick them up`,
    )
    // Visible heads-up in the terminal where opencode runs:
    console.error(
      `[donice-evaluator] wrote ${written} command file(s) to ${targetDir}. Restart OpenCode to make them available in the / menu.`,
    )
  }
}

export const DoniceEvaluatorPlugin: Plugin = async (ctx) => {
  const { client, directory, $ } = ctx

  const targetRoot = resolve(directory, ".opencode", "donice-target")
  const publicFile = join(targetRoot, PUBLIC_TARGET_FILE)
  const privateDir = join(targetRoot, PRIVATE_DIR_NAME)
  const testsDir = join(privateDir, TESTS_DIR_NAME)
  const milestonesDir = join(privateDir, MILESTONES_DIR_NAME)
  const legacyRubric = join(privateDir, LEGACY_RUBRIC_FILE)
  const pluginRoot = resolve(directory, ".opencode", "plugins")

  const protectedPrefixes = [privateDir, pluginRoot]

  const log = async (
    level: "debug" | "info" | "warn" | "error",
    message: string,
    extra?: Record<string, unknown>,
  ) => {
    try {
      await (client as any).app?.log?.({
        body: { service: "donice-evaluator", level, message, extra },
      })
    } catch {
      /* best-effort */
    }
    if (level === "error" || level === "warn") {
      console.error(`[donice-evaluator] ${level}: ${message}`, extra ?? "")
    }
  }

  const loadTarget = async (): Promise<TargetSpec | null> => {
    if (!existsSync(publicFile)) return null
    try {
      return JSON.parse(await readFile(publicFile, "utf8")) as TargetSpec
    } catch (err) {
      await log("error", "Failed to parse target.json", { err: String(err) })
      return null
    }
  }

  let target: TargetSpec | null = await loadTarget()
  if (!target) {
    await log(
      "warn",
      `No target found at ${publicFile}; plugin will idle until /donice-create runs.`,
    )
  }

  // Seed the project's .opencode/commands/ from this package's bundled
  // commands/ directory. We never overwrite — users can edit/delete the
  // installed copies and this bootstrap will leave them alone.
  await bootstrapCommands({
    bundledDir: join(PLUGIN_PKG_DIR, "commands"),
    targetDir: join(directory, ".opencode", "commands"),
    log,
  })

  // Mutable runtime state (slash commands flip these).
  const state = {
    paused: false,
    enableDeterministic: target?.enableDeterministic ?? true,
    enableLLM: target?.enableLLM ?? true,
    evaluatorModel: target?.evaluatorModel ?? {
      providerID: "anthropic",
      modelID: "claude-sonnet-4-20250514",
    },
    maxIterations: target?.maxSteerIterations ?? 25,
    cooldownMs: target?.steerCooldownMs ?? 4000,
    lastReport: null as EvalReport | null,
  }

  const evaluatorSessionIDs = new Set<string>()
  const completedSessions = new Set<string>()
  const inFlight = new Map<string, Promise<void>>()
  const iterations = new Map<string, number>()
  const lastSteerAt = new Map<string, number>()
  const milestoneIdxBySession = new Map<string, number>()

  const isProtectedPath = (raw: unknown): boolean => {
    if (typeof raw !== "string" || !raw) return false
    const abs = isAbsolute(raw) ? raw : resolve(directory, raw)
    return protectedPrefixes.some((p) => {
      const r = relative(p, abs)
      return r === "" || (!r.startsWith("..") && !isAbsolute(r))
    })
  }

  const stringMentionsProtected = (s: string): boolean => {
    if (!s) return false
    const lower = s.toLowerCase()
    return (
      lower.includes("donice-target/private") ||
      lower.includes("donice-target\\private") ||
      lower.includes(".opencode/plugins") ||
      lower.includes(".opencode\\plugins")
    )
  }

  const sanitizeID = (raw: string): string => {
    const s = raw
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 60)
    return s || `m${Date.now()}`
  }

  const getMilestones = (): Milestone[] => {
    if (!target) return []
    if (target.milestones?.length) return target.milestones
    // Legacy single-target shim: synthesize one milestone from top-level.
    return [
      {
        id: "default",
        title: target.title,
        description: target.description,
        // tests undefined → all tests run; rubric undefined → fall back to
        // legacy private/rubric.md if it exists.
        rubric: existsSync(legacyRubric) ? LEGACY_RUBRIC_FILE : undefined,
      },
    ]
  }

  const currentMilestoneIdx = (sessionID: string): number => {
    const idx = milestoneIdxBySession.get(sessionID) ?? 0
    const total = getMilestones().length
    return Math.min(idx, Math.max(total - 1, 0))
  }

  // -------------------------------------------------------------------------
  // Evaluation
  // -------------------------------------------------------------------------

  const loadDeterministicTests = async (filterNames?: string[]) => {
    if (!existsSync(testsDir)) return []
    const out: { name: string; script: string }[] = []
    for (const name of (await readdir(testsDir)).sort()) {
      if (filterNames && !filterNames.includes(name)) continue
      const full = join(testsDir, name)
      const st = await stat(full)
      if (!st.isFile()) continue
      out.push({ name, script: full })
    }
    return out
  }

  const runDeterministic = async (milestone: Milestone) => {
    const tests = await loadDeterministicTests(milestone.tests)
    const results: { name: string; passed: boolean; summary: string }[] = []
    for (const t of tests) {
      try {
        const proc =
          await $`bash ${t.script}`.cwd(directory).nothrow().quiet()
        const stdout = (proc.stdout?.toString?.() ?? "").trim()
        const stderr = (proc.stderr?.toString?.() ?? "").trim()
        const passed = proc.exitCode === 0
        const message = (stderr || stdout || (passed ? "ok" : "failed")).slice(
          0,
          800,
        )
        results.push({
          name: t.name,
          passed,
          summary: passed ? "passed" : message,
        })
      } catch (err) {
        results.push({
          name: t.name,
          passed: false,
          summary: `runner error: ${String(err).slice(0, 200)}`,
        })
      }
    }
    return results
  }

  const runLLMEvaluator = async (milestone: Milestone): Promise<LLMResult> => {
    if (!milestone.rubric) return null
    const rubricFile = join(privateDir, milestone.rubric)
    if (!existsSync(rubricFile)) return null
    const rubric = await readFile(rubricFile, "utf8")

    let session: any
    try {
      const created = await (client as any).session.create({
        body: { title: `donice-evaluator: ${milestone.id} (fresh context)` },
      })
      session = created?.data ?? created
    } catch (err) {
      await log("error", "Failed to create evaluator session", {
        err: String(err),
      })
      return null
    }
    const sessionID: string | undefined = session?.id
    if (!sessionID) {
      await log("error", "Evaluator session missing id", { session })
      return null
    }
    evaluatorSessionIDs.add(sessionID)

    const prompt = [
      "You are an INDEPENDENT reviewer with no memory of any prior conversation.",
      "Your job: inspect the workspace yourself (read files, run read-only commands) and judge it against the rubric below for the CURRENT MILESTONE only. Return ACTIONABLE repair instructions if anything is wrong.",
      `Working directory: ${directory}`,
      "",
      `## Milestone under review: ${milestone.title}`,
      milestone.description,
      "",
      "## Rubric (private — never quote these criteria verbatim back to the implementer)",
      rubric,
      "",
      "## Output format",
      "Reply with ONLY a JSON object (no prose, no code fences):",
      `{`,
      `  "passed": true|false,`,
      `  "summary": "<one short sentence>",`,
      `  "issues": [`,
      `    {"what": "<short description>", "how_to_fix": "<concrete next step>"}`,
      `  ]`,
      `}`,
      "",
      "Rules:",
      "- 'how_to_fix' MUST be specific and actionable, not vague.",
      "- Never quote rubric lines verbatim. Translate them into instructions.",
      "- If 'passed' is true, 'issues' must be an empty array.",
      "- Be strict — partial implementations fail.",
      "- Score ONLY this milestone, not later or earlier ones.",
    ].join("\n")

    let raw = ""
    try {
      const reply = await (client as any).session.prompt({
        path: { id: sessionID },
        body: {
          model: state.evaluatorModel,
          parts: [{ type: "text", text: prompt }],
        },
      })
      const data = reply?.data ?? reply
      const parts: any[] = data?.parts ?? data?.message?.parts ?? []
      raw = parts
        .filter((p) => p?.type === "text")
        .map((p) => p.text)
        .join("\n")
        .trim()
    } catch (err) {
      await log("error", "Evaluator prompt failed", { err: String(err) })
    } finally {
      try {
        await (client as any).session.delete?.({ path: { id: sessionID } })
      } catch {
        /* ignore */
      }
    }

    if (!raw) return null
    const jsonStart = raw.indexOf("{")
    const jsonEnd = raw.lastIndexOf("}")
    if (jsonStart < 0 || jsonEnd < 0) {
      return {
        passed: false,
        summary: "evaluator did not return JSON",
        issues: [
          {
            what: "evaluator produced no parseable verdict",
            how_to_fix:
              "rerun /donice-evaluate; if persistent, switch model with /donice-set-model",
          },
        ],
      }
    }
    try {
      const parsed = JSON.parse(raw.slice(jsonStart, jsonEnd + 1))
      const issues: Issue[] = Array.isArray(parsed.issues)
        ? parsed.issues
            .map((i: any) => ({
              what: String(i?.what ?? "").trim(),
              how_to_fix: String(i?.how_to_fix ?? "").trim(),
            }))
            .filter((i: Issue) => i.what || i.how_to_fix)
        : []
      return {
        passed: !!parsed.passed,
        summary: String(parsed.summary ?? "").trim(),
        issues,
      }
    } catch {
      return {
        passed: false,
        summary: "evaluator returned invalid JSON",
        issues: [
          {
            what: "evaluator output was not valid JSON",
            how_to_fix: "retry; if persistent, switch evaluator model",
          },
        ],
      }
    }
  }

  const evaluateMilestone = async (sessionID: string): Promise<EvalReport> => {
    const milestones = getMilestones()
    const idx = currentMilestoneIdx(sessionID)
    const milestone = milestones[idx]
    if (!milestone) {
      // No milestones at all → trivially complete.
      const stub: Milestone = {
        id: "none",
        title: "(no target)",
        description: "",
      }
      const r: EvalReport = {
        milestoneIdx: 0,
        milestone: stub,
        passed: true,
        detResults: [],
        llmResult: null,
        ranDeterministic: false,
        ranLLM: false,
      }
      state.lastReport = r
      return r
    }
    let detResults: EvalReport["detResults"] = []
    let llmResult: LLMResult = null
    const tasks: Promise<unknown>[] = []
    if (state.enableDeterministic) {
      tasks.push(runDeterministic(milestone).then((r) => (detResults = r)))
    }
    if (state.enableLLM) {
      tasks.push(runLLMEvaluator(milestone).then((r) => (llmResult = r)))
    }
    await Promise.all(tasks)

    const detPassed =
      !state.enableDeterministic || detResults.every((r) => r.passed)
    const llmPassed =
      !state.enableLLM || (llmResult ? llmResult.passed : true)
    const report: EvalReport = {
      milestoneIdx: idx,
      milestone,
      passed: detPassed && llmPassed,
      detResults,
      llmResult,
      ranDeterministic: state.enableDeterministic,
      ranLLM: state.enableLLM,
    }
    state.lastReport = report
    return report
  }

  const buildSteerPrompt = (report: EvalReport): string => {
    const milestones = getMilestones()
    const lines: string[] = []
    lines.push(
      `## Steering update — milestone ${report.milestoneIdx + 1}/${milestones.length}: ${report.milestone.title}`,
    )
    lines.push(
      "Independent evaluators just inspected this milestone. It is **not yet satisfied**. Keep working — only THIS milestone matters right now.",
    )
    lines.push("")
    const failedDet = report.detResults.filter((r) => !r.passed)
    if (failedDet.length) {
      lines.push("### Deterministic checks failing")
      for (const r of failedDet) {
        lines.push(`- **${r.name}** — ${r.summary}`)
      }
      lines.push("")
    }
    const passedDet = report.detResults.filter((r) => r.passed)
    if (passedDet.length) {
      lines.push("### Deterministic checks passing")
      for (const r of passedDet) lines.push(`- ${r.name}`)
      lines.push("")
    }
    if (report.llmResult && !report.llmResult.passed) {
      lines.push("### Reviewer (fresh-context LLM) feedback")
      if (report.llmResult.summary) {
        lines.push(`Summary: ${report.llmResult.summary}`)
      }
      if (report.llmResult.issues.length) {
        lines.push("")
        lines.push("**How to fix**")
        for (const i of report.llmResult.issues) {
          if (i.what && i.how_to_fix) {
            lines.push(`- *${i.what}* — ${i.how_to_fix}`)
          } else {
            lines.push(`- ${i.what || i.how_to_fix}`)
          }
        }
      }
      lines.push("")
    }
    lines.push(
      "Continue iterating on the current milestone only. The evaluation scripts and rubric are intentionally hidden — use the failure messages and 'How to fix'
…[文件过长——中段 8KB 抽样]…
ot be re-checked.",
    ].join("\n")
  }

  const triggerSteer = async (sessionID: string) => {
    if (!target) return
    if (state.paused) return
    if (evaluatorSessionIDs.has(sessionID)) return
    if (completedSessions.has(sessionID)) return
    if (!state.enableDeterministic && !state.enableLLM) return
    const last = lastSteerAt.get(sessionID) ?? 0
    if (Date.now() - last < state.cooldownMs) return
    if (inFlight.has(sessionID)) return

    const job = (async () => {
      lastSteerAt.set(sessionID, Date.now())
      const iter = (iterations.get(sessionID) ?? 0) + 1
      iterations.set(sessionID, iter)
      if (iter > state.maxIterations) {
        await log("warn", "Max steer iterations hit; halting steering", {
          sessionID,
          iter,
        })
        try {
          await (client as any).session.prompt({
            path: { id: sessionID },
            body: {
              noReply: true,
              parts: [
                {
                  type: "text",
                  text: `## donice-evaluator: steering halted\n\nReached the configured max of ${state.maxIterations} iterations. Use \`/donice-resume\` after raising the cap or \`/donice-reset\`.`,
                },
              ],
            },
          })
        } catch {}
        return
      }

      let report: EvalReport
      try {
        report = await evaluateMilestone(sessionID)
      } catch (err) {
        await log("error", "Evaluation failed", { err: String(err) })
        return
      }

      if (report.passed) {
        const milestones = getMilestones()
        const idx = report.milestoneIdx
        if (idx + 1 < milestones.length) {
          // Advance to next milestone.
          milestoneIdxBySession.set(sessionID, idx + 1)
          try {
            await (client as any).session.prompt({
              path: { id: sessionID },
              body: {
                parts: [
                  {
                    type: "text",
                    text: buildAdvancePrompt(
                      idx,
                      milestones[idx + 1],
                      milestones.length,
                    ),
                  },
                ],
              },
            })
          } catch (err) {
            await log("warn", "Failed to post advance notice", {
              err: String(err),
            })
          }
          return
        }
        // Final milestone passed.
        completedSessions.add(sessionID)
        try {
          await (client as any).session.prompt({
            path: { id: sessionID },
            body: {
              noReply: true,
              parts: [
                {
                  type: "text",
                  text: `## donice-evaluator: target satisfied ✅\n\nAll ${milestones.length} milestones passed. You can stop now.`,
                },
              ],
            },
          })
        } catch (err) {
          await log("warn", "Failed to post completion notice", {
            err: String(err),
          })
        }
        return
      }

      try {
        await (client as any).session.prompt({
          path: { id: sessionID },
          body: { parts: [{ type: "text", text: buildSteerPrompt(report) }] },
        })
      } catch (err) {
        await log("error", "Failed to send steering prompt", {
          err: String(err),
        })
      }
    })()

    inFlight.set(sessionID, job)
    try {
      await job
    } finally {
      inFlight.delete(sessionID)
    }
  }

  // -------------------------------------------------------------------------
  // Target authoring (donice_init_target tool)
  // -------------------------------------------------------------------------

  type Plan = {
    title: string
    description: string
    evaluatorModel?: { providerID: string; modelID: string }
    enableDeterministic?: boolean
    enableLLM?: boolean
    maxSteerIterations?: number
    steerCooldownMs?: number
    overwrite?: boolean
    milestones: Array<{
      id?: string
      title: string
      description: string
      tests?: Array<{ filename: string; content: string }>
      rubric?: string
    }>
  }

  const writeTargetFromPlan = async (planRaw: string): Promise<string> => {
    let plan: Plan
    try {
      plan = JSON.parse(planRaw)
    } catch (err) {
      throw new Error(`planJSON is not valid JSON: ${String(err)}`)
    }
    if (
      typeof plan.title !== "string" ||
      typeof plan.description !== "string" ||
      !Array.isArray(plan.milestones) ||
      plan.milestones.length === 0
    ) {
      throw new Error(
        "plan must include title, description, and a non-empty milestones[] array",
      )
    }
    if (existsSync(publicFile) && !plan.overwrite) {
      throw new Error(
        "target.json already exists. Set overwrite=true in the plan, or have the user delete .opencode/donice-target/ first.",
      )
    }

    // Sanitize milestone IDs and ensure uniqueness.
    const seen = new Set<string>()
    const milestones = plan.milestones.map((m, idx) => {
      let id = sanitizeID(m.id || m.title || `milestone-${idx + 1}`)
      let suffix = 1
      while (seen.has(id)) id = `${id}-${++suffix}`
      seen.add(id)
      return { ...m, id }
    })

    // Reset hidden directories so old artifacts don't leak.
    for (const dir of [testsDir, milestonesDir]) {
      if (existsSync(dir)) await rm(dir, { recursive: true, force: true })
    }
    await mkdir(testsDir, { recursive: true })
    await mkdir(milestonesDir, { recursive: true })

    const targetSpec: TargetSpec = {
      title: plan.title,
      description: plan.description,
      evaluatorModel: plan.evaluatorModel ?? state.evaluatorModel,
      enableDeterministic: plan.enableDeterministic ?? true,
      enableLLM: plan.enableLLM ?? true,
      maxSteerIterations: plan.maxSteerIterations ?? state.maxIterations,
      steerCooldownMs: plan.steerCooldownMs ?? state.cooldownMs,
      milestones: [],
    }

    const written: string[] = []

    for (const m of milestones) {
      const writtenTests: string[] = []
      for (const t of m.tests ?? []) {
        if (!t?.filename || !t?.content) continue
        const safeName = t.filename.replace(/[^a-zA-Z0-9._-]/g, "_")
        const filePath = join(testsDir, safeName)
        await writeFile(filePath, t.content, "utf8")
        await $`chmod +x ${filePath}`.nothrow().quiet()
        writtenTests.push(safeName)
        written.push(`tests/${safeName}`)
      }

      let rubricRel: string | undefined
      if (typeof m.rubric === "string" && m.rubric.trim()) {
        rubricRel = `${MILESTONES_DIR_NAME}/${m.id}.md`
        await mkdir(dirname(join(privateDir, rubricRel)), { recursive: true })
        await writeFile(join(privateDir, rubricRel), m.rubric, "utf8")
        written.push(rubricRel)
      }

      targetSpec.milestones!.push({
        id: m.id,
        title: m.title,
        description: m.description,
        tests: writtenTests.length ? writtenTests : undefined,
        rubric: rubricRel,
      })
    }

    await mkdir(targetRoot, { recursive: true })
    await writeFile(publicFile, JSON.stringify(targetSpec, null, 2), "utf8")
    written.unshift("target.json")

    // Update in-memory state.
    target = targetSpec
    state.enableDeterministic = targetSpec.enableDeterministic ?? true
    state.enableLLM = targetSpec.enableLLM ?? true
    state.evaluatorModel = targetSpec.evaluatorModel ?? state.evaluatorModel
    state.maxIterations = targetSpec.maxSteerIterations ?? state.maxIterations
    state.cooldownMs = targetSpec.steerCooldownMs ?? state.cooldownMs
    state.lastReport = null
    completedSessions.clear()
    iterations.clear()
    milestoneIdxBySession.clear()
    lastSteerAt.clear()

    await log("info", "donice_init_target wrote a new target", {
      milestones: milestones.length,
      files: written.length,
    })

    return [
      `✅ Wrote target.json with ${milestones.length} milestone(s):`,
      ...milestones.map((m, i) => `  ${i + 1}. ${m.title} (${m.id})`),
      "",
      `Files written under .opencode/donice-target/: ${written.length}`,
      "",
      "Next: start a fresh session
…[仅保留首 16KB/中段 8KB/末 8KB]…
ied`,
          "",
          formatStatus(sessionID),
        ].join("\n")
      }
      case "donice-advance": {
        const milestones = getMilestones()
        const idx = currentMilestoneIdx(sessionID)
        if (idx + 1 >= milestones.length) {
          return "Already on the final milestone."
        }
        milestoneIdxBySession.set(sessionID, idx + 1)
        completedSessions.delete(sessionID)
        return `Advanced to milestone ${idx + 2}/${milestones.length}: **${milestones[idx + 1].title}**.`
      }
      case "donice-pause":
        state.paused = true
        return "⏸ donice steering paused. Use `/donice-resume` to re-enable."
      case "donice-resume":
        state.paused = false
        completedSessions.delete(sessionID)
        return "▶ donice steering resumed."
      case "donice-toggle": {
        const which = a.toLowerCase()
        if (which === "det" || which === "deterministic") {
          state.enableDeterministic = !state.enableDeterministic
          return `deterministic evaluator: **${state.enableDeterministic ? "on" : "off"}**`
        }
        if (which === "llm" || which === "reviewer") {
          state.enableLLM = !state.enableLLM
          return `llm reviewer: **${state.enableLLM ? "on" : "off"}**`
        }
        return "Usage: `/donice-toggle det` or `/donice-toggle llm`."
      }
      case "donice-list-models":
        return listModels()
      case "donice-set-model": {
        if (!a) {
          return "Usage: `/donice-set-model <providerID>/<modelID>` — try `/donice-list-models` first."
        }
        const slash = a.indexOf("/")
        if (slash < 0) {
          return "Format must be `<providerID>/<modelID>`."
        }
        state.evaluatorModel = {
          providerID: a.slice(0, slash).trim(),
          modelID: a.slice(slash + 1).trim(),
        }
        return `evaluator model set to \`${state.evaluatorModel.providerID}/${state.evaluatorModel.modelID}\``
      }
      case "donice-reset":
        iterations.delete(sessionID)
        completedSessions.delete(sessionID)
        lastSteerAt.delete(sessionID)
        milestoneIdxBySession.delete(sessionID)
        return "session state reset (iteration counter, completion flag, milestone index)."
      case "donice-reload":
        target = await loadTarget()
        return target
          ? `reloaded target: **${target.title}** (${getMilestones().length} milestone(s))`
          : "no target.json found"
      case "donice-create":
        return createKickoffPrompt()
      case "donice-launch":
        return buildLaunchPrompt(sessionID)
      default:
        return ""
    }
  }

  // -------------------------------------------------------------------------
  // Plugin hooks
  // -------------------------------------------------------------------------

  return {
    tool: {
      donice_init_target: tool({
        description:
          "Authoring tool for donice-evaluator. Writes target.json plus deterministic test scripts and milestone rubrics into the protected private/ directory in one atomic step. Pass a JSON-encoded plan as planJSON. Use this only after gathering the user's approval — typically as the final step of /donice-create.",
        args: {
          planJSON: tool.schema
            .string()
            .describe(
              "JSON-encoded plan: {title, description, overwrite?, evaluatorModel?, enableDeterministic?, enableLLM?, maxSteerIterations?, steerCooldownMs?, milestones:[{id?, title, description, tests?:[{filename, content}], rubric?}]}",
            ),
        },
        async execute(args) {
          return await writeTargetFromPlan(args.planJSON)
        },
      }),
    },

    "experimental.chat.system.transform": async (input, output) => {
      if (!target) return
      if (evaluatorSessionIDs.has(input.sessionID ?? "")) return
      const milestones = getMilestones()
      const sessionID = input.sessionID ?? ""
      const idx = currentMilestoneIdx(sessionID)
      const cur = milestones[idx]
      const lines: string[] = []
      lines.push("## donice-evaluator: assigned target")
      lines.push(`Overall: **${target.title}** — ${target.description}`)
      if (milestones.length) {
        lines.push("")
        lines.push(
          `### Current milestone — ${idx + 1}/${milestones.length}: ${cur.title}`,
        )
        lines.push(cur.description)
        if (idx + 1 < milestones.length) {
          lines.push("")
          lines.push("Upcoming milestone titles (revealed for context only — focus on the current one):")
          for (let i = idx + 1; i < milestones.length; i++) {
            lines.push(`- ${i + 1}. ${milestones[i].title}`)
          }
        }
      }
      lines.push("")
      lines.push(
        "Independent evaluators (deterministic scripts you cannot read, plus a fresh-context reviewer LLM) judge ONLY the current milestone after every idle, then advance you. They will keep prompting with concrete 'How to fix' hints until every criterion passes. Do not try to read or modify `.opencode/donice-target/private/` or `.opencode/plugins/` — those paths are blocked. The user can run `/donice-status`, `/donice-milestone`, `/donice-evaluate`, `/donice-pause`, `/donice-resume`, `/donice-toggle`, `/donice-list-models`, `/donice-set-model`, `/donice-advance`, `/donice-reset`, `/donice-reload`, `/donice-create`, `/donice-launch`.",
      )
      output.system.push(lines.join("\n"))
    },

    "tool.execute.before": async (input, output) => {
      // Our own tool is allowed to write into private/.
      if (input.tool === "donice_init_target") return
      const args = output.args ?? {}
      const candidates: unknown[] = [
        args.filePath,
        args.path,
        args.file,
        args.target,
        args.directory,
      ]
      if (candidates.some(isProtectedPath)) {
        await log("warn", "Blocked tool access to protected path", {
          tool: input.tool,
          args,
        })
        throw new Error(
          `[donice-evaluator] '${input.tool}' is not permitted to read or modify the evaluator's private directories. The criteria are intentionally hidden — work from the public target description.`,
        )
      }
      if (
        (input.tool === "bash" || input.tool === "shell") &&
        typeof args.command === "string" &&
        stringMentionsProtected(args.command)
      ) {
        await log("warn", "Blocked shell command referencing protected path", {
          command: args.command,
        })
        throw new Error(
          `[donice-evaluator] commands referencing the evaluator's private directories are blocked.`,
        )
      }
      if (
        (input.tool === "grep" ||
          input.tool === "glob" ||
          input.tool === "list" ||
          input.tool === "ls") &&
        typeof args.pattern === "string" &&
        stringMentionsProtected(args.pattern)
      ) {
        throw new Error(
          `[donice-evaluator] search patterns into the evaluator's private directories are blocked.`,
        )
      }
    },

    "command.execute.before": async (input, output) => {
      const cmd = input.command
      if (!cmd || !cmd.startsWith("donice-")) return
      const text = await handleCommand(
        cmd,
        input.arguments ?? "",
        input.sessionID,
      )
      if (!text) return
      output.parts = [{ type: "text", text }]
    },

    event: async ({ event }) => {
      if (!event || typeof event !== "object") return
      const type = (event as any).type
      const props = (event as any).properties ?? {}
      const sessionID: string | undefined = props.sessionID ?? props.id
      if (!sessionID) return
      if (type === "session.idle") {
        triggerSteer(sessionID).catch((err) =>
          log("error", "triggerSteer failed", { err: String(err) }),
        )
      }
      if (type === "session.deleted") {
        evaluatorSessionIDs.delete(sessionID)
        completedSessions.delete(sessionID)
        iterations.delete(sessionID)
        lastSteerAt.delete(sessionID)
        milestoneIdxBySession.delete(sessionID)
      }
    },
  }
}

export default DoniceEvaluatorPlugin
